194	  TaskflowEventPayload,
195	  TaskflowEventType,
196	  Unsubscribe,
197	} from "@/types/event";
198	
199	/**
200	 * In-process, typed publish/subscribe bus.
201	 *
202	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
203	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
204	 * every reactive concern `subscribe()`s at module init (see
205	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
206	 * throwing handler never fails the emit or the sibling handlers.
207	 */
208	
209	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
210	
211	const handlers = new Map<TaskflowEventType, HandlerSet>();
212	
213	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
214	
215	/** Registers a handler for one event type. Call the return value to detach. */
216	export function subscribe<K extends TaskflowEventType>(
217	  type: K,
218	  handler: EventHandler<K>,
219	): Unsubscribe {
220	  const set = handlers.get(type) ?? new Set();
221	  set.add(handler as EventHandler<TaskflowEventType>);
222	  handlers.set(type, set);
223	  return () => {
224	    set.delete(handler as EventHandler<TaskflowEventType>);
225	  };
226	}
227	
228	/** Registers a handler that detaches itself after the first delivery. */
229	export function subscribeOnce<K extends TaskflowEventType>(
230	  type: K,
231	  handler: EventHandler<K>,
232	): Unsubscribe {
233	  const off = subscribe(type, (payload) => {
234	    off();
235	    return handler(payload);
236	  });
237	  return off;
238	}
239	
240	/**
241	 * Publishes an event to every subscriber. Resolves once all handlers settle;
242	 * rejected handlers are reported to the error sinks, never rethrown.
243	 */
244	export async function emit<K extends TaskflowEventType>(
245	  type: K,
246	  payload: TaskflowEventPayload<K>,
247	): Promise<void> {
248	  const set = handlers.get(type);
249	  if (!set || set.size === 0) return;
250	
251	  const results = await Promise.allSettled(
252	    [...set].map(async (handler) => {
253	      await (handler as EventHandler<K>)(payload);
254	    }),
255	  );
256	
257	  for (const result of results) {
258	    if (result.status === "rejected") {
259	      reportHandlerError(type, result.reason);
260	    }
261	  }
262	}
263	
264	/** Fire-and-forget variant for call sites that must not await delivery. */
265	export function emitAndForget<K extends TaskflowEventType>(
266	  type: K,
267	  payload: TaskflowEventPayload<K>,
268	): void {
269	  void emit(type, payload).catch((error: unknown) => {
270	    reportHandlerError(type, error);
271	  });
272	}
273	
274	export function onHandlerError(
275	  sink: (type: TaskflowEventType, error: unknown) => void,
276	): Unsubscribe {
277	  errorSinks.add(sink);
278	  return () => {
279	    errorSinks.delete(sink);
280	  };
281	}
282	
283	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
284	  for (const sink of errorSinks) {
285	    try {
286	      sink(type, error);
287	    } catch {
288	      // A failing error sink must never escalate.
289	    }
290	  }
291	}
292	
293	/** Number of live subscribers for an event; used by tests and diagnostics. */
294	export function subscriberCount(type: TaskflowEventType): number {
295	  return handlers.get(type)?.size ?? 0;
296	}
297	
298	/** Detaches every handler. Test-only — never call from application code. */
299	export function resetEventBus(): void {
300	  handlers.clear();
301	  errorSinks.clear();
302	}
