305	---PAGING
306	/**
307	 * Private paging helpers shared by the repositories in this directory.
308	 *
309	 * Not part of the public data-access surface — repositories re-export nothing
310	 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
311	 * so a page boundary is stable even when two rows share a `created_at`.
312	 */
313	import { sql } from "drizzle-orm";
314	import { decodeCursor, encodeCursor } from "./base-repository";
315	import { makePage } from "@/types/common";
316	import type { Page } from "@/types/common";
317	import type { SQL } from "drizzle-orm";
318	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
319	
320	export interface KeysetSort {
321	  readonly sortColumn: SQLiteColumn;
322	  readonly idColumn: SQLiteColumn;
323	}
324	
325	/**
326	 * Predicate that resumes a descending listing after `cursor`. Returns
327	 * `undefined` for a first page or an unparseable cursor — a bad cursor
328	 * degrades to "start from the top", never to an error page.
329	 */
330	export function keysetPredicate(
331	  sort: KeysetSort,
332	  cursor: string | null | undefined,
333	): SQL | undefined {
334	  if (!cursor) return undefined;
335	  const decoded = decodeCursor(cursor);
336	  if (!decoded) return undefined;
337	
338	  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
339	}
340	
341	/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
342	export function probeLimit(limit: number): number {
343	  return Math.max(1, Math.min(limit, 100)) + 1;
344	}
345	
346	/**
347	 * Turns an over-fetched row array into a `Page`, dropping the probe row and
348	 * deriving the next cursor from the last row that survived.
349	 */
350	export function toPage<TRow, TOut>(
351	  rows: readonly TRow[],
352	  limit: number,
353	  total: number,
354	  map: (row: TRow) => TOut,
355	  cursorOf: (row: TRow) => { id: string; sortValue: string },
356	): Page<TOut> {
357	  const capped = Math.max(1, Math.min(limit, 100));
358	  const hasMore = rows.length > capped;
359	  const visible = hasMore ? rows.slice(0, capped) : rows;
360	  const last = visible.at(-1);
361	
362	  const nextCursor =
363	    hasMore && last
364	      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
365	      : null;
366	
367	  return makePage(visible.map(map), nextCursor, total);
368	}
369	
370	/** Drops the `undefined` slots so `and(...)` never sees a hole. */
371	export function compact(
372	  ...predicates: readonly (SQL | undefined)[]
373	): readonly SQL[] {
374	  return predicates.filter((value): value is SQL => value !== undefined);
375	}
