713	/**
714	 * Streams the audit-log CSV; requires `activity:export`.
715	 *
716	 * Owner D. `activity:export` sits above `activity:read` in `ROLE_MATRIX` —
717	 * reading the feed in the UI and walking off with the whole audit trail are
718	 * different privileges.
719	 *
720	 * Must call (do not reimplement): can, isEnabled, toCsv
721	 */
722	
723	import { errorResponse, failure } from "@/app/api/_lib/responses";
724	import { getActor } from "@/lib/actor";
725	import { csvResponseHeaders, toCsv } from "@/lib/csv";
726	import { isEnabled } from "@/lib/feature-flags";
727	import { can } from "@/lib/permissions";
728	import { exportActivitySchema } from "@/schemas/activity";
729	import { listActivity } from "@/server/services/activity-service";
730	import { buildFlagContext } from "@/server/services/feature-flag-service";
731	import { getOrganizationSummary } from "@/server/services/organization-service";
732	import type { ActivityEvent } from "@/types/activity";
733	
734	export const dynamic = "force-dynamic";
735	
736	const EXPORT_PAGE_LIMIT = 100;
737	
738	const COLUMNS: readonly string[] = [
739	  "occurredAt",
740	  "action",
741	  "actorId",
742	  "subjectKind",
743	  "subjectId",
744	  "projectId",
745	  "summary",
746	];
747	
748	export async function GET(request: Request): Promise<Response> {
749	  try {
750	    const url = new URL(request.url);
751	    const orgSlug = url.searchParams.get("orgSlug");
752	    if (orgSlug === null) {
753	      return failure("validation_failed", "orgSlug is required.");
754	    }
755	
756	    const actor = await getActor(orgSlug);
757	    const { organization } = await getOrganizationSummary(actor, actor.orgId);
758	
759	    if (!can(actor, "activity:export", { kind: "activity", orgId: actor.orgId })) {
760	      return failure("forbidden", "Exporting the audit log requires an admin.");
761	    }
762	
763	    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
764	      return failure("forbidden", "CSV export is not included in this plan.");
765	    }
766	
767	    const parsed = exportActivitySchema.safeParse({
768	      orgId: actor.orgId,
769	      since: url.searchParams.get("since"),
770	      until: url.searchParams.get("until"),
771	      format: url.searchParams.get("format") ?? "csv",
772	    });
773	    if (!parsed.success) {
774	      return failure(
775	        "validation_failed",
776	        "since and until must be ISO-8601 timestamps.",
777	      );
778	    }
779	
780	    const page = await listActivity(actor, {
781	      orgId: parsed.data.orgId,
782	      since: parsed.data.since,
783	      until: parsed.data.until,
784	      limit: EXPORT_PAGE_LIMIT,
785	    });
786	
787	    if (parsed.data.format === "json") {
788	      return Response.json({ items: page.items, total: page.total });
789	    }
790	
791	    const csv = toCsv(page.items.map(toRow), COLUMNS);
792	    return new Response(csv, {
793	      headers: csvResponseHeaders(`taskflow-activity-${organization.slug}.csv`),
794	    });
795	  } catch (error) {
796	    return errorResponse(error);
797	  }
798	}
