813	---CSV
814	/**
815	 * RFC-4180 CSV writer used by both export routes (issues and the audit log).
816	 *
817	 * The rules that matter: fields containing a comma, a double quote or a line
818	 * break are wrapped in double quotes and every embedded quote is doubled;
819	 * rows are separated by CRLF; column order comes from the caller, never from
820	 * object key order.
821	 */
822	
823	const NEEDS_QUOTING = /[",\r\n]/;
824	
825	export function escapeCsvValue(value: string | number | boolean | null): string {
826	  if (value === null) return "";
827	  const text = String(value);
828	  if (!NEEDS_QUOTING.test(text)) return text;
829	  return `"${text.replace(/"/g, '""')}"`;
830	}
831	
832	/**
833	 * Serialises `rows` using `columns` as both the header line and the field
834	 * order. A column missing from a row is written as an empty field.
835	 */
836	export function toCsv(
837	  rows: readonly Readonly<Record<string, string | number | boolean | null>>[],
838	  columns: readonly string[],
839	): string {
840	  const lines: string[] = [columns.map(escapeCsvValue).join(",")];
841	
