/**
 * Bounds are re-serialised to the canonical millisecond form the log stores,
 * so "…:03Z" and "…:03.000Z" name the same instant in the string comparison.
 */
const rangeBoundSchema = isoTimestampSchema.transform((value) =>
  toIsoTimestamp(value),
);

/** A range that ends before it starts is refused rather than read as empty. */
const rangeOrderRefinement = {
  message: "until must not be earlier than since",
  path: ["until"],
} as const;

export const activityFilterSchema = z
  .object({
    orgId: orgIdSchema,
    action: z.array(activityActionSchema).optional(),
    actorId: userIdSchema.optional(),
    projectId: projectIdSchema.optional(),
    subjectKind: activitySubjectKindSchema.optional(),
    since: rangeBoundSchema.optional(),
    until: rangeBoundSchema.optional(),
  })
  .extend(pageRequestSchema.shape)
  .refine(
    (range) =>
      range.since === undefined ||
      range.until === undefined ||
      range.since <= range.until,
    rangeOrderRefinement,
  );

export const exportActivitySchema = z
  .object({
    orgId: orgIdSchema,
    since: rangeBoundSchema,
    until: rangeBoundSchema,
    format: z.enum(["csv", "json"]).default("csv"),
  })
  .refine((range) => range.since <= range.until, rangeOrderRefinement);

export type ActivityFilterInput = z.infer<typeof activityFilterSchema>;
export type ExportActivityInput = z.infer<typeof exportActivitySchema>;

