        summary: `Role ${payload.from} → ${payload.to}`,
        metadata: { from: payload.from, to: payload.to },
        occurredAt: payload.occurredAt,
      }).then(() => undefined),
    ),
    subscribe("member.removed", (payload) =>
      record(payload.orgId, "member.removed", {
        actorId: payload.actorId,
        subjectKind: "member",
        subjectId: payload.memberId,
        projectId: null,
        summary: "Removed member",
        metadata: { userId: payload.userId },
        occurredAt: payload.occurredAt,
      }).then(() => undefined),
    ),
    subscribe("billing.plan_changed", (payload) =>
      record(payload.orgId, "billing.plan_changed", {
        actorId: payload.actorId,
        subjectKind: "subscription",
        subjectId: payload.orgId,
        projectId: null,
        summary: `Plan ${payload.from} → ${payload.to}`,
        metadata: { from: payload.from, to: payload.to },
        occurredAt: payload.occurredAt,
      }).then(() => undefined),
    ),
    subscribe("flag.toggled", (payload) =>
      record(payload.orgId, "flag.toggled", {
        actorId: payload.actorId,
        subjectKind: "feature_flag",
        subjectId: payload.flag,
        projectId: null,
        summary: `${payload.enabled ? "Enabled" : "Disabled"} feature ${payload.flag}`,
        metadata: { flag: payload.flag, enabled: payload.enabled },
        occurredAt: payload.occurredAt,
      }).then(() => undefined),
    ),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/** Refuses a range that ends before it starts; the schemas refuse the same for parsed input. */
function assertRangeOrder(
  since: IsoTimestamp | undefined,
  until: IsoTimestamp | undefined,
): void {
  if (since === undefined || until === undefined) return;
  if (new Date(since).getTime() > new Date(until).getTime()) {
    throw new Error("until must not be earlier than since");
  }
}

